import{_ as n,o as a,c as s,a2 as o}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"Hand-offs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/handoffs.md","filePath":"guide/handoffs.md","lastUpdated":1793532400000}'),t={name:"guide/handoffs.md"};function r(c,e,d,l,i,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="hand-offs" tabindex="-1">Hand-offs <a class="header-anchor" href="#hand-offs" aria-label="Permalink to &quot;Hand-offs&quot;">​</a></h1><p>A tool can start a run of its <strong>own agent</strong>: <code>startHandoff(ctx, { payload, idempotencyKey?, concurrencyKey?, address? })</code>. The new run (the child) has its own budget, its own approvals and its own concurrency key, and the calling run (the parent) goes on at once: a hand-off is fire and forget. A daily run that finds ten pull requests needing work hands off one run per pull request instead of fixing them all inline under one budget.</p><p>Hand-offs are not delegation: nothing waits for the child, and nothing of its result comes back to the parent. The tool gets <code>{ runId, deduplicated }</code> and that is all.</p><h2 id="opting-in" tabindex="-1">Opting in <a class="header-anchor" href="#opting-in" aria-label="Permalink to &quot;Opting in&quot;">​</a></h2><p>An agent accepts hand-offs only with <code>handoff.on()</code> in its channels. The child comes in on the channel <code>agent</code> (subscription id <code>handoff</code>), which <code>agentChannel()</code> registers:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> maintainer = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;maintainer&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Every morning, hand off each pull request that needs work.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [</span></span>
<span class="line"><span style="color:#E6DFDE;">        cron.on(</span><span style="color:#E7C58C;">&#39;0 6 * * *&#39;</span><span style="color:#E6DFDE;">),</span></span>
<span class="line"><span style="color:#958A8B;">        // the opt-in: runs of this agent may start runs of this agent</span></span>
<span class="line"><span style="color:#E6DFDE;">        handoff.on({</span></span>
<span class="line"><span style="color:#E6DFDE;">            schema: z.object({ pr: z.string() }),</span></span>
<span class="line"><span style="color:#E6DFDE;">            concurrencyKey: (p) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> p.pr,</span></span>
<span class="line"><span style="color:#E6DFDE;">            maxPerRun: </span><span style="color:#E7C58C;">20</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    ],</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: { hand_off_pr: handOffPr },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store: createMemoryStore(),</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents: [maintainer],</span></span>
<span class="line"><span style="color:#958A8B;">    // a bare engine lists the agent channel; @chamvi/app contributes it</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [cronChannel(), agentChannel()],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>With <a href="/guide/app"><code>@chamvi/app</code></a> the engine module contributes <code>agentChannel()</code>, so the name <code>agent</code> is taken (a user channel of that name clashes at setup). Without <code>handoff.on()</code> a call is a <code>ValidationError</code> tool error: <code>Agent &quot;&lt;a&gt;&quot; accepts no hand-offs: add handoff.on() to its channels.</code></p><p><code>handoff.on(options?)</code> takes:</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>schema</code></td><td>A Standard Schema the payload goes through; the child gets the parsed value. A failing payload is a <code>ValidationError</code> tool error and starts nothing. Without one the payload passes unchanged</td></tr><tr><td><code>maxPerRun</code></td><td>How many hand-offs one run may start over all its executions, default <code>DEFAULT_MAX_HANDOFFS_PER_RUN</code> (100). A positive integer, else <code>InvalidAgentDefinitionError</code> (also for a subscription built by hand, when the agent is registered)</td></tr><tr><td><code>concurrencyKey(payload)</code></td><td>The child&#39;s concurrency key when the call gives none</td></tr><tr><td><code>idempotencyKey(payload)</code></td><td>The child&#39;s idempotency key when the call gives none</td></tr></tbody></table><h2 id="starting-a-hand-off" tabindex="-1">Starting a hand-off <a class="header-anchor" href="#starting-a-hand-off" aria-label="Permalink to &quot;Starting a hand-off&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> handOffPr = defineTool({</span></span>
<span class="line"><span style="color:#E6DFDE;">    description: </span><span style="color:#E7C58C;">&#39;Starts a run of its own for one pull request that needs work.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    inputSchema: z.object({ pr: z.string().describe(</span><span style="color:#E7C58C;">&#39;owner/repo#number&#39;</span><span style="color:#E6DFDE;">) }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> ({ pr }, { context }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#958A8B;">        // the day the daily run was fired, not the wall clock: a redo keeps the key</span></span>
<span class="line"><span style="color:#FF7B84;">        const</span><span style="color:#E6DFDE;"> day = context.run.trigger.receivedAt.toISOString().slice(</span><span style="color:#E7C58C;">0</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">10</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">        return</span><span style="color:#E6DFDE;"> startHandoff(context, {</span></span>
<span class="line"><span style="color:#E6DFDE;">            payload: { pr },</span></span>
<span class="line"><span style="color:#E6DFDE;">            idempotencyKey: </span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">pr</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">@</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">day</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            address: pr,</span></span>
<span class="line"><span style="color:#E6DFDE;">        });</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><ul><li><code>payload</code> is required; <code>idempotencyKey</code>, <code>concurrencyKey</code> and <code>address</code> are optional non-empty strings without NUL (the concurrency key and the address at most 255 characters). Anything else is a <code>ValidationError</code> tool error.</li><li>The child&#39;s envelope is <code>{ agent: &lt;own agent&gt;, trigger: &#39;handoff&#39;, channel: &#39;agent&#39;, payload, idempotencyKey, concurrencyKey?, address?, invoker?, parent }</code>. The model sees the channel, the subscription id and the payload, like any run.</li><li><code>startHandoff()</code> runs inside a tool call only; in the tools factory it throws <code>InvalidRunStateError</code>.</li></ul><h2 id="keys-and-dedupe-across-runs" tabindex="-1">Keys and dedupe across runs <a class="header-anchor" href="#keys-and-dedupe-across-runs" aria-label="Permalink to &quot;Keys and dedupe across runs&quot;">​</a></h2><p>The claimed idempotency key is <code>handoff:&lt;key&gt;</code> (or <code>sha256:&lt;hex&gt;</code> of it when it is longer than 255 characters), where <code>&lt;key&gt;</code> is the call&#39;s <code>idempotencyKey</code>, else the subscription&#39;s <code>idempotencyKey(payload)</code>, else <code>&lt;parent run id&gt;:&lt;hash of payload, concurrency key and address&gt;</code>.</p><p>A given key is <strong>not</strong> scoped to the parent run: a second run that hands off the same key (the job run again, a replica) gets the first child back with <code>deduplicated: true</code>. Key it by what makes the work unique, for example the pull request and the day (<code>\${pr}@\${day}</code>), taking the day from <code>ctx.run.trigger.receivedAt</code> so a redo keeps the same key. Without a key, the default is scoped to the parent, so another parent with the same payload starts its own child. The idempotency scope is <code>&lt;agent&gt;:agent</code> (plus the invoker, see below), apart from every other channel&#39;s.</p><p>The concurrency key works as for any run: two children with the same key never run at the same time, so one key per pull request keeps two fixes of one pull request apart.</p><h2 id="the-effect-record" tabindex="-1">The effect record <a class="header-anchor" href="#the-effect-record" aria-label="Permalink to &quot;The effect record&quot;">​</a></h2><p>Each call is recorded under the effect key <code>&lt;runId&gt;:handoff:&lt;hash of payload, key, concurrency key and address&gt;</code> with the value <code>{ runId, deduplicated }</code>, so a step redone after a crash or after an approval returns the recorded result and starts nothing. Identical calls in one step (parallel tool calls) share one hand-off. Dispatch is idempotent by itself, so a crash between the dispatch and the record still yields one child (the redo reads <code>deduplicated: true</code>).</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Per run</strong>: at most <code>maxPerRun</code> hand-offs, counted durably across executions (the effect <code>handoff-count:&lt;runId&gt;</code>), so a run that paused on an approval keeps its count. The count goes up before the dispatch, also for a deduplicated one; a crash in between spends that call&#39;s slot, and its redo reuses the slot (it never fails at the limit). Past the limit: <code>Run &lt;id&gt; reached its &lt;n&gt; hand-offs (handoff.on({ maxPerRun })).</code></li><li><strong>Depth 1</strong> (<code>MAX_HANDOFF_DEPTH</code>): a handed-off run cannot hand off again (<code>A handed-off run cannot hand off again (depth 1).</code>), so a fan-out never recurses.</li><li><strong>The invoker</strong> is inherited: the child gets the parent&#39;s invoker snapshot (none for a cron parent), so <code>requireToolPermission()</code> decides the same in the child as in the parent and a hand-off never widens grants. The agent, the invoker and the parent come from the engine&#39;s copy of the run, so tool code that writes to <code>ctx.run</code> cannot change what a hand-off starts.</li></ul><h2 id="outbound-in-a-child" tabindex="-1">Outbound in a child <a class="header-anchor" href="#outbound-in-a-child" aria-label="Permalink to &quot;Outbound in a child&quot;">​</a></h2><p>The <code>agent</code> channel has no <code>out</code>, so <code>ctx.channels.findOne()</code> without a name is <code>undefined</code> in a child. Tools of a child name their channel and address, for example <code>ctx.channels.findOneOrFail(&#39;github&#39;).approve({ address: &#39;o/r#5&#39;, title: &#39;Merge?&#39; })</code>. The <code>address</code> given to <code>startHandoff()</code> becomes the child&#39;s <code>trigger.address</code> and <code>run.address</code> (shown in the dashboard), so a tool can read it back from <code>ctx.run.trigger.address</code>.</p><h2 id="lineage" tabindex="-1">Lineage <a class="header-anchor" href="#lineage" aria-label="Permalink to &quot;Lineage&quot;">​</a></h2><p>The child&#39;s <code>trigger.parent</code> is <code>{ kind: &#39;handoff&#39;, runId, agent, depth: 1 }</code> (<code>TriggerParent</code>). Only <code>startHandoff()</code> sets it: <code>engine.dispatch()</code> and a channel&#39;s <code>ctx.dispatch()</code> drop a <code>parent</code> a caller passes, so nobody forges lineage. It lives in the stored envelope, so both repositories keep it without a migration. The <a href="/guide/ui">dashboard</a>&#39;s run page shows &quot;handed off from&quot; with a link to the parent run.</p><h2 id="under-chamvi-run-job" tabindex="-1">Under <code>chamvi run-job</code> <a class="header-anchor" href="#under-chamvi-run-job" aria-label="Permalink to &quot;Under \`chamvi run-job\`&quot;">​</a></h2><p>A <a href="/guide/scheduler#one-shot-jobs">one-shot job</a> starts a whole engine over the shared store, so it may pick up the children its run handed off. The drain at the end of the job interrupts the children still running; they requeue through recovery on the deployment and go on from their latest checkpoint.</p>`,27)])])}const f=n(t,[["render",r]]);export{u as __pageData,f as default};
